import subprocess, sys, os, shutil, hashlib
BASE="/tmp/explore/_example_master"
def mk(name, files=None, delete=None, fresh=True):
    d=f"/tmp/explore/check-command/t/{name}"
    if fresh and os.path.exists(d): shutil.rmtree(d)
    if fresh: shutil.copytree(BASE,d)
    for f in (delete or []):
        p=os.path.join(d,f)
        if os.path.isdir(p): shutil.rmtree(p)
        elif os.path.exists(p): os.remove(p)
    for k,v in (files or {}).items():
        p=os.path.join(d,k)
        os.makedirs(os.path.dirname(p),exist_ok=True)
        if isinstance(v,bytes): open(p,'wb').write(v)
        else: open(p,'w').write(v)
    return d
def run(d, args=("check",), cwd=None):
    r=subprocess.run(["/workspace/executable",*args],cwd=cwd or d,capture_output=True)
    return r.returncode, r.stdout.decode('utf-8','replace'), r.stderr.decode('utf-8','replace')
def show(name, d, args=("check",)):
    rc,o,e=run(d,args)
    print(f"===== {name} exit={rc}")
    print("--stdout--"); print(repr(o))
    print("--stderr--"); print(repr(e))
    return rc,o,e
PYEOF
